from collections import deque
class Solution:
    def closestNode(self, n: int, edges: List[List[int]], query: List[List[int]]) -> List[int]:
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b); adj[b].append(a)
        def bfs(src):
            dist = [-1] * n
            dist[src] = 0
            dq = deque([src])
            while dq:
                u = dq.popleft()
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        dq.append(v)
            return dist
        res = []
        for s, e, nd in query:
            ds, de, dn = bfs(s), bfs(e), bfs(nd)
            best, bd = -1, float('inf')
            for v in range(n):
                if ds[v] != -1 and ds[v] + de[v] == ds[e] and dn[v] < bd:
                    bd, best = dn[v], v
            res.append(best)
        return res

