class Solution {
public:
    vector<int> closestNode(int n, vector<vector<int>>& edges, vector<vector<int>>& query) {
        vector<vector<int>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        auto bfs = [&](int src) {
            vector<int> dist(n, -1);
            queue<int> q; q.push(src); dist[src] = 0;
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int v : adj[u]) if (dist[v] == -1) { dist[v] = dist[u] + 1; q.push(v); }
            }
            return dist;
        };
        vector<int> res;
        for (auto& qr : query) {
            auto ds = bfs(qr[0]), de = bfs(qr[1]), dn = bfs(qr[2]);
            int best = -1, bd = INT_MAX;
            for (int v = 0; v < n; v++)
                if (ds[v] + de[v] == ds[qr[1]] && dn[v] < bd) { bd = dn[v]; best = v; }
            res.push_back(best);
        }
        return res;
    }
};

