class Solution {
    private List<List<Integer>> adj;
    private int[] bfs(int src, int n) {
        int[] dist = new int[n]; Arrays.fill(dist, -1);
        Queue<Integer> q = new LinkedList<>(); q.add(src); dist[src] = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj.get(u)) if (dist[v] == -1) { dist[v] = dist[u] + 1; q.add(v); }
        }
        return dist;
    }
    public int[] closestNode(int n, int[][] edges, int[][] query) {
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int[] res = new int[query.length];
        for (int i = 0; i < query.length; i++) {
            int[] ds = bfs(query[i][0], n), de = bfs(query[i][1], n), dn = bfs(query[i][2], n);
            int best = -1, bd = Integer.MAX_VALUE;
            for (int v = 0; v < n; v++)
                if (ds[v] + de[v] == ds[query[i][1]] && dn[v] < bd) { bd = dn[v]; best = v; }
            res[i] = best;
        }
        return res;
    }
}

