var closestNode = function(n, edges, query) {
    const adj = Array.from({length: n}, () => []);
    for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
    const bfs = (src) => {
        const dist = new Array(n).fill(-1);
        dist[src] = 0;
        const q = [src];
        for (let h = 0; h < q.length; h++) {
            const u = q[h];
            for (const v of adj[u]) if (dist[v] === -1) { dist[v] = dist[u] + 1; q.push(v); }
        }
        return dist;
    };
    return query.map(([s, e, nd]) => {
        const ds = bfs(s), de = bfs(e), dn = bfs(nd);
        let best = -1, bd = Infinity;
        for (let v = 0; v < n; v++)
            if (ds[v] + de[v] === ds[e] && dn[v] < bd) { bd = dn[v]; best = v; }
        return best;
    });
};

