class Solution:
    def closestNode(self, n, edges, query):
        import sys
        sys.setrecursionlimit(5000)
        LOG = 11
        adj = [[] for _ in range(n)]
        for a, b in edges: adj[a].append(b); adj[b].append(a)
        par = [[0]*LOG for _ in range(n)]; dep = [0]*n
        def dfs(u, p):
            par[u][0] = p
            for v in adj[u]:
                if v != p:
                    dep[v] = dep[u] + 1; dfs(v, u)
        dfs(0, 0)
        for k in range(1, LOG):
            for u in range(n): par[u][k] = par[par[u][k-1]][k-1]
        def lca(a, b):
            if dep[a] < dep[b]: a, b = b, a
            for k in range(LOG-1, -1, -1):
                if dep[a] - (1<<k) >= dep[b]: a = par[a][k]
            if a == b: return a
            for k in range(LOG-1, -1, -1):
                if par[a][k] != par[b][k]: a, b = par[a][k], par[b][k]
            return par[a][0]
        def anc_on(u, target_dep):
            for k in range(LOG-1, -1, -1):
                if dep[u] - (1<<k) >= target_dep: u = par[u][k]
            return u
        res = []
        for s, e, nd in query:
            m = lca(s, e)
            c1 = anc_on(nd, dep[m]) if lca(nd, s) == m or lca(nd, m) == m else None
            cand = []
            if lca(nd, s) == m: cand.append(anc_on(nd, dep[s]))
            if lca(nd, e) == m: cand.append(anc_on(nd, dep[e]))
            best = min(cand, key=lambda v: abs(dep[nd] - dep[v]))
            res.append(best)
        return res

